            <x-filament-panels::avatar.user :user="$user" />
        </button>
    </x-slot>

    <x-filament::dropdown.list>
        @if (($profileItem?->isVisible() ?? true) && $hasProfileItem)
            <x-filament::dropdown.list.item
                :color="$profileItem?->getColor()"
